interface.definition:
a!localVariables(
  local!currentUsers: #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12611615"(),
  local!editingby: if(
    a!isNullOrEmpty(local!currentUsers),
    {},
  index(local!currentUsers,"c2",{}).[1]
  ),
#"SYSTEM_SYSRULES_formLayout_v1"(
  label: "",
  contents: {
    #"SYSTEM_SYSRULES_richTextDisplayField"(
      value:{
        #"SYSTEM_SYSRULES_richTextItem_v1"(
          text: "Role Definition Operations",
          color: "ACCENT",
          size: "MEDIUM_PLUS",
          style: "STRONG"
        )
      }
    ),
    #"SYSTEM_SYSRULES_sectionLayout_v1"(divider: "ABOVE"),
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      contents: {
        #"SYSTEM_SYSRULES_cardLayout"(
          contents: {
            #"SYSTEM_SYSRULES_sideBySideLayout"(
              items: {

                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      value: {
                        char(9),
                        #"SYSTEM_SYSRULES_richTextIcon"(
                          icon: "warning",
                          color: "NEGATIVE",
                          size: "EXTRA_LARGE"
                        )
                      }
                    ),
                    width: "MINIMIZE"
                  ),
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      value: {
                        char(10),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: "It is currently being edited by ",
                          size: "MEDIUM",
                          color: "NEGATIVE",
                          style: "STRONG"
                        ),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text:  local!editingby,
                          size: "MEDIUM",
                          color: "ACCENT",
                          style: "STRONG"
                        ),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: " Please come back later to make the changes",
                          size: "MEDIUM",
                          color: "NEGATIVE",
                          style: "STRONG"
                        )
                      }
                    )
                  )

              }
            )
          },
          showWhen: if(
            or(a!isNullOrEmpty(local!currentUsers), tostring(local!editingby) = loggedInUser()),
            false,
            true
          )
        ),
        #"SYSTEM_SYSRULES_textField"(readOnly: true),
        #"SYSTEM_SYSRULES_radioButtonField"(
          label:"Select an operation",
          choiceLabels: {"Update Category","Add New Category", "Delete a Category"},
          choiceValues: {"Update Category","Add New Category", "Delete a Category"},
          value: ri!operation,
          saveInto: ri!operation,
          disabled:  if(
            or(a!isNullOrEmpty(local!currentUsers), tostring(local!editingby) = loggedInUser()),
            false,
            true
          )
        )
      }
    )
  },
  buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
    primaryButtons: {
      #"SYSTEM_SYSRULES_ButtonWidget"(
        label: "NEXT",
        submit: true,
        style: "PRIMARY",
        saveInto: a!save(ri!buttonValue,"NEXT"),
        disabled: if(
          a!isNullOrEmpty(ri!operation),
          true,
          false
        ),
       confirmHeader:  "Please make the changes in 30 mins else your changes would be lost." ,
       cancelButtonLabel: "NO",
       confirmButtonLabel: "PROCEED"
      )
    }
  )
)
)
